const int LED = 9, ZUMMER = 8;

void setup() { pinMode(LED, OUTPUT); pinMode(ZUMMER, OUTPUT); }

void loop() {
  // BLOK:  <10 marta takrorla>
  //            <LEDni yoq> <0.2 s kut> <LEDni o'chir> <0.2 s kut>
