  digitalWrite(CHIROQ_PIN, qorongi ? HIGH : LOW);

  Serial.print("yorug'lik = "); Serial.print(yoruglik);
  Serial.println(qorongi ? "  -> chiroq YONIQ" : "  -> chiroq o'chiq");

  delay(100);
}
